export const brushes=[
  {id:'pencil',name:'Pencil',description:'Soft graphite'},
  {id:'fineliner',name:'Ink pen',description:'Clean, even ink'},
  {id:'brush',name:'Ink brush',description:'Expressive width'},
  {id:'fountain',name:'Fountain pen',description:'Angled ink nib'}
];
const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));
const number=(n,fallback)=>Number.isFinite(n)?n:fallback;
const fmt=n=>Number(n.toFixed(3));
export function settings(values={}){return {brush:brushes.some(b=>b.id===values.brush)?values.brush:'fineliner',color:/^#[\da-f]{6}$/i.test(values.color||'')?values.color:'#292536',stroke:clamp(number(values.stroke,2.5),1,30),smoothing:clamp(number(values.smoothing,0),0,100)};}
export function pointerPoint(event,position){return {...position,time:number(event.timeStamp,0),pressure:event.pointerType==='pen'&&event.pressure>0?clamp(event.pressure,0,1):null};}
function interpolate(a,b,t){return {x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t,time:number(a.time,0)+(number(b.time,0)-number(a.time,0))*t,pressure:a.pressure==null||b.pressure==null?null:a.pressure+(b.pressure-a.pressure)*t};}
function resample(points){const length=points.slice(1).reduce((sum,p,i)=>sum+Math.hypot(p.x-points[i].x,p.y-points[i].y),0),spacing=Math.max(2,length/4000);const output=[{...points[0]}];let remaining=spacing;for(let i=1;i<points.length;i++){let a=points[i-1],b=points[i],distance=Math.hypot(b.x-a.x,b.y-a.y);while(distance>=remaining&&distance>1e-6){const p=interpolate(a,b,remaining/distance);output.push(p);a=p;distance=Math.hypot(b.x-a.x,b.y-a.y);remaining=spacing;}remaining-=distance;}const last=points.at(-1);if(Math.hypot(output.at(-1).x-last.x,output.at(-1).y-last.y)>1e-6)output.push({...last});else output[output.length-1]={...last};return output;}
export function smoothPoints(raw,amount=0){if(!raw.length)return [];if(raw.length<3||amount<=0)return raw.map(p=>({...p}));let points=resample(raw);const strength=clamp(amount,0,100)/100,passes=Math.ceil(2+strength*18);for(let pass=0;pass<passes;pass++){points=points.map((p,i)=>{if(i===0||i===points.length-1)return p;const a=points[i-1],b=points[i+1],mix=strength*.48;return {...p,x:p.x+(a.x+b.x-2*p.x)*mix,y:p.y+(a.y+b.y-2*p.y)*mix};});}return points;}
export function centerPath(points,curved=false){if(!points.length)return '';let d=`M ${fmt(points[0].x)} ${fmt(points[0].y)}`;if(points.length===1)return d;if(!curved||points.length===2)return d+points.slice(1).map(p=>` L ${fmt(p.x)} ${fmt(p.y)}`).join('');if(curved==='complete'){for(let i=0;i<points.length-1;i++){const p0=points[Math.max(0,i-1)],p1=points[i],p2=points[i+1],p3=points[Math.min(points.length-1,i+2)],c1={x:p1.x+(p2.x-p0.x)/6,y:p1.y+(p2.y-p0.y)/6},c2={x:p2.x-(p3.x-p1.x)/6,y:p2.y-(p3.y-p1.y)/6};d+=` C ${fmt(c1.x)} ${fmt(c1.y)} ${fmt(c2.x)} ${fmt(c2.y)} ${fmt(p2.x)} ${fmt(p2.y)}`;}return d;}for(let i=1;i<points.length-1;i++){const p=points[i],next=points[i+1];d+=` Q ${fmt(p.x)} ${fmt(p.y)} ${fmt((p.x+next.x)/2)} ${fmt((p.y+next.y)/2)}`;}const last=points.at(-1);return d+` L ${fmt(last.x)} ${fmt(last.y)}`;}
function widths(points,style){let previous=.7;return points.map((p,i)=>{const before=points[Math.max(0,i-1)],after=points[Math.min(points.length-1,i+1)],dx=after.x-before.x,dy=after.y-before.y,dt=Math.max(5,number(after.time,0)-number(before.time,0)),speed=Math.hypot(dx,dy)/dt;const pressure=p.pressure==null?clamp(.95-speed*.3,.3,.95):clamp(p.pressure,.05,1);previous=previous*.65+pressure*.35;if(style.brush==='fountain'){const length=Math.hypot(dx,dy)||1,normalX=-dy/length,normalY=dx/length,nib=Math.abs(normalX*Math.cos(-Math.PI/4)+normalY*Math.sin(-Math.PI/4));return style.stroke*(.17+nib*.85)*(.7+previous*.45);}return style.stroke*(.25+previous*1.25);});}
function outline(points,sizes){if(points.length===1){const p=points[0],r=sizes[0]/2;return `M ${fmt(p.x-r)} ${fmt(p.y)} a ${fmt(r)} ${fmt(r)} 0 1 0 ${fmt(r*2)} 0 a ${fmt(r)} ${fmt(r)} 0 1 0 ${fmt(-r*2)} 0`;}const left=[],right=[];for(let i=0;i<points.length;i++){const before=points[Math.max(0,i-1)],after=points[Math.min(points.length-1,i+1)],dx=after.x-before.x,dy=after.y-before.y,length=Math.hypot(dx,dy)||1,r=sizes[i]/2;left.push({x:points[i].x-dy/length*r,y:points[i].y+dx/length*r});right.push({x:points[i].x+dy/length*r,y:points[i].y-dx/length*r});}const chain=[...left,...right.reverse()];return centerPath(chain,false)+' Z';}
export function strokeGeometry(raw,values={}){const style=settings(values),points=smoothPoints(raw,style.smoothing),path=centerPath(points,style.smoothing>=98?'complete':style.smoothing>0);if(!points.length)return {style,points,path,outline:'',widths:[]};const sizes=['brush','fountain'].includes(style.brush)?widths(points,style):points.map(()=>style.stroke);return {style,points,path,outline:outline(points,sizes),widths:sizes};}
export function strokeMarkup(raw,values={},hitWidth=0){const g=strokeGeometry(raw,values),s=g.style;if(!g.points.length)return '';let visible='';if(s.brush==='brush'||s.brush==='fountain'||g.points.length===1){visible=`<path d="${g.outline}" fill="${s.color}" opacity="${s.brush==='pencil'?.55:1}"/>`;}else if(s.brush==='pencil'){const second=g.points.map((p,i)=>({...p,x:p.x+Math.sin(i*1.9)*s.stroke*.15,y:p.y+Math.cos(i*1.7)*s.stroke*.15}));visible=`<path d="${g.path}" fill="none" stroke="${s.color}" stroke-width="${s.stroke*.85}" opacity=".48" stroke-linecap="round" stroke-linejoin="round"/><path d="${centerPath(second,s.smoothing>=98?'complete':s.smoothing>0)}" fill="none" stroke="${s.color}" stroke-width="${s.stroke*.3}" opacity=".36" stroke-linecap="round" stroke-linejoin="round"/>`;}else visible=`<path d="${g.path}" fill="none" stroke="${s.color}" stroke-width="${s.stroke}" stroke-linecap="round" stroke-linejoin="round"/>`;return visible+(hitWidth?`<path class="vector-hit" d="${g.path}" fill="none" stroke="transparent" stroke-width="${Math.max(hitWidth,s.stroke*2)}" stroke-linecap="round"/>`:'');}
export function drawingObject(raw,values={}){if(!raw.length)throw new Error('A drawing needs at least one point.');const style=settings(values),pad=style.stroke*2;const bounds=raw.reduce((b,p)=>({minX:Math.min(b.minX,p.x),minY:Math.min(b.minY,p.y),maxX:Math.max(b.maxX,p.x),maxY:Math.max(b.maxY,p.y)}),{minX:Infinity,minY:Infinity,maxX:-Infinity,maxY:-Infinity});const x=bounds.minX-pad,y=bounds.minY-pad,w=Math.max(1,bounds.maxX-bounds.minX+pad*2),h=Math.max(1,bounds.maxY-bounds.minY+pad*2);return {type:'pen',x,y,w,h,baseW:w,baseH:h,points:raw.map(p=>({...p,x:p.x-x,y:p.y-y})),...style};}
export const previewPoints=Array.from({length:45},(_,i)=>({x:8+i*4.5,y:32+Math.sin(i/7)*12+Math.sin(i*1.6)*2,time:i*12,pressure:.25+Math.sin(i/44*Math.PI)*.65}));
